-- ── A.J. Fernandez ──
UPDATE `brands` SET `gamme` = '[{"name":"New World","color":"#5C4033","force":"Full","wrapper":"San Andrés Maduro","vitolas":["Robusto","Toro"],"story":"L''assemblage qui a fait connaître la maison sous son propre nom. Cape mexicaine sombre, fumée épaisse, notes de café brûlé et de poivre noir — puissant sans être agressif, ce qui est précisément la signature de la maison."},{"name":"Bellas Artes","color":"#8B6914","force":"Medium","wrapper":"Habano Rosado","vitolas":["Toro"],"story":"Le registre médium de la maison, plus boisé et plus sec. Celui qu''on donne à qui trouve New World trop dense, et qui montre que la force n''a jamais été le sujet."},{"name":"Enclave","color":"#8B3A1E","force":"Medium-Full","wrapper":"Habano d''Équateur","vitolas":[],"story":"2016 — une ligne de la maison, que le recensement de cet atlas prenait pour une marque à part."},{"name":"Días de Gloria","color":"#4A3728","force":"Full","wrapper":"Puro nicaraguayen","vitolas":[],"story":"2020 — les jours de gloire : un puro nicaraguayen des fermes de la maison."},{"name":"Sosa","color":"#6B4226","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Les marques de la famille Sosa — Sosa Classic, Imperio Cubano —, rachetées en décembre 2016 et roulées au Nicaragua depuis janvier 2017. Elles sortaient jusque-là de la fabrique n° 4 d''Arturo Fuente, où Juan Sosa assemble depuis 1997. Le recensement de cet atlas prenait Sosa pour une maison dominicaine."}]' WHERE `name` = 'A.J. Fernandez';
UPDATE `brands` SET `gamme_en` = '[{"name":"New World","color":"#5C4033","force":"Full","wrapper":"San Andrés Maduro","vitolas":["Robusto","Toro"],"story":"The blend that made the house known under its own name. Dark Mexican wrapper, thick smoke, notes of burnt coffee and black pepper — powerful without being aggressive, which is precisely the signature of the house."},{"name":"Bellas Artes","color":"#8B6914","force":"Medium","wrapper":"Habano Rosado","vitolas":["Toro"],"story":"The medium register of the house, drier and woodier. The one to hand to anyone who finds New World too dense, and proof that strength was never the point."},{"name":"Enclave","color":"#8B3A1E","force":"Medium-Full","wrapper":"Ecuadorian Habano","vitolas":[],"story":"2016 — a line of the house, which this atlas''s census took for a separate brand."},{"name":"Días de Gloria","color":"#4A3728","force":"Full","wrapper":"Nicaraguan puro","vitolas":[],"story":"2020 — the days of glory: a Nicaraguan puro from the house''s farms."},{"name":"Sosa","color":"#6B4226","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"The Sosa family''s brands — Sosa Classic, Imperio Cubano —, bought in December 2016 and rolled in Nicaragua since January 2017. Until then they came out of Arturo Fuente''s factory no. 4, where Juan Sosa has blended since 1997. This atlas''s census took Sosa for a Dominican house."}]' WHERE `name` = 'A.J. Fernandez';
UPDATE `brands` SET `gamme_es` = '[{"name":"New World","color":"#5C4033","force":"Full","wrapper":"San Andrés Maduro","vitolas":["Robusto","Toro"],"story":"La liga que dio a conocer la casa bajo su propio nombre. Capa mexicana oscura, humo espeso, notas de café tostado y pimienta negra — potente sin ser agresivo, que es precisamente la firma de la casa."},{"name":"Bellas Artes","color":"#8B6914","force":"Medium","wrapper":"Habano Rosado","vitolas":["Toro"],"story":"El registro medio de la casa, más seco y más amaderado. El que se ofrece a quien encuentra New World demasiado denso, y que demuestra que la fuerza nunca fue el asunto."},{"name":"Enclave","color":"#8B3A1E","force":"Medium-Full","wrapper":"Habano de Ecuador","vitolas":[],"story":"2016 — una línea de la casa, que el censo de este atlas tomaba por una marca aparte."},{"name":"Días de Gloria","color":"#4A3728","force":"Full","wrapper":"Puro nicaragüense","vitolas":[],"story":"2020 — los días de gloria: un puro nicaragüense de las fincas de la casa."},{"name":"Sosa","color":"#6B4226","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"Las marcas de la familia Sosa — Sosa Classic, Imperio Cubano —, compradas en diciembre de 2016 y liadas en Nicaragua desde enero de 2017. Salían hasta entonces de la fábrica n.º 4 de Arturo Fuente, donde Juan Sosa liga desde 1997. El censo de este atlas tomaba Sosa por una casa dominicana."}]' WHERE `name` = 'A.J. Fernandez';
UPDATE `brands` SET `gamme_de` = '[{"name":"New World","color":"#5C4033","force":"Full","wrapper":"San Andrés Maduro","vitolas":["Robusto","Toro"],"story":"Der Blend, der das Haus unter eigenem Namen bekannt machte. Dunkles mexikanisches Deckblatt, dichter Rauch, Noten von geröstetem Kaffee und schwarzem Pfeffer — kraftvoll, ohne aggressiv zu sein, und genau das ist die Handschrift des Hauses."},{"name":"Bellas Artes","color":"#8B6914","force":"Medium","wrapper":"Habano Rosado","vitolas":["Toro"],"story":"Das mittlere Register des Hauses, trockener und holziger. Die Zigarre für alle, denen New World zu dicht ist — und der Beweis, dass es nie um Stärke ging."},{"name":"Enclave","color":"#8B3A1E","force":"Medium-Full","wrapper":"Ecuadorianisches Habano","vitolas":[],"story":"2016 — eine Linie des Hauses, die die Zählung dieses Atlas für eine eigene Marke hielt."},{"name":"Días de Gloria","color":"#4A3728","force":"Full","wrapper":"Nicaraguanischer Puro","vitolas":[],"story":"2020 — die Tage des Ruhms: ein nicaraguanischer Puro von den Farmen des Hauses."},{"name":"Sosa","color":"#6B4226","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Die Marken der Familie Sosa — Sosa Classic, Imperio Cubano —, im Dezember 2016 gekauft und seit Januar 2017 in Nicaragua gerollt. Bis dahin kamen sie aus der Fabrik Nr. 4 von Arturo Fuente, wo Juan Sosa seit 1997 blendet. Die Zählung dieses Atlas hielt Sosa für ein dominikanisches Haus."}]' WHERE `name` = 'A.J. Fernandez';
UPDATE `brands` SET `gamme_zh` = '[{"name":"New World","color":"#5C4033","force":"Full","wrapper":"San Andrés Maduro","vitolas":["Robusto","Toro"],"story":"让这家企业以自己名义为人所知的配方。深色墨西哥茄衣，烟雾厚实，带焦咖啡与黑胡椒气息——浓郁而不咄咄逼人，这正是这家企业的签名。"},{"name":"Bellas Artes","color":"#8B6914","force":"Medium","wrapper":"Habano Rosado","vitolas":["Toro"],"story":"这家企业的中度之作，更干、更偏木质。适合觉得新世界过于厚重的人，也证明力度从来不是重点。"},{"name":"Enclave","color":"#8B3A1E","force":"Medium-Full","wrapper":"厄瓜多尔 Habano","vitolas":[],"story":"2016年——公司的一条线，本图集的普查曾把它当作独立品牌。"},{"name":"Días de Gloria","color":"#4A3728","force":"Full","wrapper":"尼加拉瓜纯料","vitolas":[],"story":"2020年——光荣岁月：来自公司自家农场的尼加拉瓜纯料。"},{"name":"Sosa","color":"#6B4226","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"索萨家族的品牌——Sosa Classic、Imperio Cubano——2016年12月买下，2017年1月起在尼加拉瓜卷制。此前出自 Arturo Fuente 的四号厂，胡安·索萨自1997年起在那里调配。本图集的普查曾把 Sosa 当作一家多米尼加公司。"}]' WHERE `name` = 'A.J. Fernandez';
UPDATE `brands` SET `gamme_ar` = '[{"name":"New World","color":"#5C4033","force":"Full","wrapper":"San Andrés Maduro","vitolas":["Robusto","Toro"],"story":"الخلطة التي عرّفت بالدار باسمها هي. غلاف مكسيكي داكن، دخان كثيف، ونفحات قهوة محروقة وفلفل أسود — قوّة دون عدوانية، وهذا تحديداً توقيع الدار."},{"name":"Bellas Artes","color":"#8B6914","force":"Medium","wrapper":"Habano Rosado","vitolas":["Toro"],"story":"المستوى المتوسط للدار، أكثر جفافاً وخشبية. يُقدَّم لمن يجد نيو وورلد ثقيلاً، ويثبت أن القوّة لم تكن يوماً هي الغاية."},{"name":"Enclave","color":"#8B3A1E","force":"Medium-Full","wrapper":"هابانو إكوادوري","vitolas":[],"story":"2016 — خطّ من خطوط الدار، كان إحصاء هذا الأطلس يحسبه علامة مستقلّة."},{"name":"Días de Gloria","color":"#4A3728","force":"Full","wrapper":"نيكاراغوي خالص","vitolas":[],"story":"2020 — أيّام المجد: سيجار نيكاراغوي خالص من مزارع الدار."},{"name":"Sosa","color":"#6B4226","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"علامات عائلة سوسا — Sosa Classic وImperio Cubano — اشتُريت في كانون الأوّل/ديسمبر 2016 وتُلفّ في نيكاراغوا منذ كانون الثاني/يناير 2017. كانت تخرج حتى ذلك الحين من مصنع Arturo Fuente رقم 4، حيث يمزج خوان سوسا منذ 1997. وكان إحصاء هذا الأطلس يحسب Sosa دارًا دومينيكية."}]' WHERE `name` = 'A.J. Fernandez';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; requalification : cigaraficionado.com « A.J. Fernandez To Acquire Sosa Cigars » (19 décembre 2016 : rachat des seules marques de la famille Sosa — Sosa Classic, Imperio Cubano, Santa Julia… — faites jusque-là à la fabrique n° 4 de Tabacalera A. Fuente par Juan Sosa, chez Fuente depuis 1997 ; production passée au Nicaragua chez A.J. Fernández dès janvier 2017)') WHERE `name` = 'A.J. Fernandez' AND COALESCE(`source`,'') NOT LIKE '%requalification :%';

-- ── General Cigar ──
UPDATE `brands` SET `gamme` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"La gamme la plus vendue de la maison aux États-Unis. Cape Connecticut Shade, douce et crémeuse, sur assemblage dominicain et jamaïcain. Notes de crème, cèdre léger, noisette. Format Café Baron de Rothschild (42 x 127mm). Le cigare des terrasses ensoleillées et des après-midi sans urgence.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"Série inspirée des moteurs Harley-Davidson V-twin, aux formats nommés d''après des pièces : V660 Carb, V554 Piston, V770 Engine. Cape d''Équateur sur nicaraguayen et hondurien. Corsée, notes de cuir, café noir, chocolat. Cigare de route et d''Amérique profonde.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Équateur"},{"name":"Punch Upper Cut","color":"#722F37","force":"Full","story":"La gamme haute de General Cigar sous le nom Punch. Cape maduro du Honduras sur nicaraguayen et hondurien. Notes de chocolat noir, bois fumé, poivre. La face obscure de Punch — puissante là où la gamme classique est accessible.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Maduro du Honduras"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Le portefeuille de la famille Toraño, racheté en septembre 2014 — les marques seulement ; la société Toraño Family Cigar a cessé, et Charlie Toraño est resté consultant. Carlos Toraño est mort en février 2022. L''atlas avait supprimé un « Carlos Toraño Panama » inventé (204) ; la marque Toraño, elle, est réelle et vit ici."}]' WHERE `name` = 'General Cigar';
UPDATE `brands` SET `gamme_en` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"America''s best-seller for 30 years. Connecticut Shade wrapper, soft and creamy, over Dominican-Jamaican blend. Notes of cream, light cedar, hazelnut. The cigar of sunny terraces and unhurried afternoons. Consistent, accessible, never disappointing.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"Series inspired by Harley-Davidson V-twin engines. Format names: V660 Carb, V554 Piston, V770 Engine. Ecuadorian wrapper over Nicaraguan-Honduran. Full body, notes of motorcycle leather, black coffee, chocolate, engine oil (really). A cigar of the open road, freedom, deep America.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Ecuadorian"},{"name":"Punch Upper Cut","color":"#722F37","force":"Full","story":"The premium General Cigar range under the Punch label. Honduran maduro wrapper over Nicaraguan-Honduran. Notes of dark chocolate, smoky wood, pepper. The dark side of Punch — powerful where the classic range is accessible.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Honduran Maduro"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"The Toraño family''s portfolio, bought in September 2014 — the brands only; the Toraño Family Cigar company ceased, and Charlie Toraño stayed on as a consultant. Carlos Toraño died in February 2022. This atlas had deleted an invented \\"Carlos Toraño Panama\\" (204); the Toraño brand itself is real and lives here."}]' WHERE `name` = 'General Cigar';
UPDATE `brands` SET `gamme_es` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"El superventas estadounidense desde hace treinta años. Capa Connecticut Shade suave y cremosa sobre liga dominicano-jamaicana. Crema, cedro ligero, avellana. Formato Café Baron de Rothschild (42 x 127mm). El puro de las terrazas soleadas y de las tardes sin prisa. Regular, accesible, nunca decepciona.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"Serie inspirada en los motores V-twin de Harley-Davidson, con formatos bautizados como piezas: V660 Carb, V554 Piston, V770 Engine. Capa de Ecuador sobre tripa nicaragüense y hondureña. Potente, con notas de cuero, café negro y chocolate. Un puro de carretera y de la América profunda.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Ecuador"},{"name":"Punch Upper Cut","color":"#722F37","force":"Full","story":"La gama premium de General Cigar bajo la etiqueta Punch. Capa hondureña maduro sobre nicaragüense-hondureño. Chocolate negro, madera ahumada, pimienta. La cara oscura de Punch: potente allí donde la gama clásica es accesible.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Maduro de Honduras"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"El portafolio de la familia Toraño, comprado en septiembre de 2014 — solo las marcas; la sociedad Toraño Family Cigar cesó, y Charlie Toraño quedó como consultor. Carlos Toraño murió en febrero de 2022. Este atlas había suprimido un «Carlos Toraño Panamá» inventado (204); la marca Toraño, en cambio, es real y vive aquí."}]' WHERE `name` = 'General Cigar';
UPDATE `brands` SET `gamme_de` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"Der amerikanische Bestseller seit dreißig Jahren. Mildes, cremiges Connecticut-Shade-Deckblatt über dominikanisch-jamaikanischer Mischung. Sahne, leichte Zeder, Haselnuss. Format Café Baron de Rothschild (42 x 127 mm). Die Zigarre für sonnige Terrassen und Nachmittage ohne Eile. Gleichmäßig, zugänglich, nie enttäuschend.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"Eine Serie, inspiriert von den V-Twin-Motoren von Harley-Davidson, mit Formaten, die wie Bauteile heißen: V660 Carb, V554 Piston, V770 Engine. Deckblatt aus Ecuador über nicaraguanischer und honduranischer Einlage. Kräftig, mit Noten von Leder, schwarzem Kaffee und Schokolade. Eine Zigarre der Landstraße und des tiefen Amerika.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Ecuador"},{"name":"Punch Upper Cut","color":"#722F37","force":"Full","story":"Die Premiumserie von General Cigar unter dem Label Punch. Honduranisches Maduro-Deckblatt über Nicaraguanisch-Honduranischem. Zartbitterschokolade, Rauchholz, Pfeffer. Die dunkle Seite von Punch — kraftvoll dort, wo die klassische Serie zugänglich ist.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Maduro aus Honduras"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Das Portfolio der Familie Toraño, im September 2014 gekauft — nur die Marken; die Gesellschaft Toraño Family Cigar hörte auf, und Charlie Toraño blieb Berater. Carlos Toraño starb im Februar 2022. Dieser Atlas hatte ein erfundenes „Carlos Toraño Panama“ gelöscht (204); die Marke Toraño selbst ist real und lebt hier."}]' WHERE `name` = 'General Cigar';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"三十年来的美国畅销之作。柔和奶油般的康涅狄格阴植茄衣，内裹多米尼加与牙买加配方。奶油、轻盈雪松、榛子。Café Baron de Rothschild 规格（42 x 127 毫米）。这是阳光露台与不赶时间的午后的雪茄。稳定、平易，从不让人失望。","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"这一系列取材于哈雷戴维森的 V-twin 发动机，各规格以零件命名：V660 Carb、V554 Piston、V770 Engine。厄瓜多尔茄衣，包裹尼加拉瓜与洪都拉斯茄芯。风格厚重，带皮革、黑咖啡与巧克力的气息——属于公路与美国腹地的一支雪茄。","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"厄瓜多尔"},{"name":"Punch Upper Cut","color":"#722F37","force":"Full","story":"General Cigar 以 Punch 之名推出的高端系列。洪都拉斯马杜罗茄衣，内裹尼加拉瓜与洪都拉斯烟叶。黑巧克力、烟熏木、胡椒。这是 Punch 阴暗的一面——在经典系列平易之处，它选择强劲。","vitolas":["Robusto","Toro","Churchill"],"wrapper":"洪都拉斯 Maduro"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"托拉尼奥家族的品牌组合，2014年9月买下——只有品牌；Toraño Family Cigar 公司停业，查理·托拉尼奥留任顾问。卡洛斯·托拉尼奥2022年2月去世。本图集曾删除一个杜撰的「Carlos Toraño Panama」（204）；Toraño 品牌本身是真实的，在这里延续。"}]' WHERE `name` = 'General Cigar';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"الأكثر مبيعًا في أمريكا منذ ثلاثين عامًا. غلاف كونيتيكت شيد لطيف وقشديّ فوق خلطة دومينيكية-جامايكية. قشدة، أرز خفيف، بندق. قياس كافيه بارون دي روتشيلد (42 × 127 مم). سيجار الشرفات المشمسة والأصائل بلا عجلة. منتظم، سهل المنال، لا يخيّب.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"سلسلة مستوحاة من محرّكات هارلي ديفيدسون ثنائية الأسطوانة، بقياسات تحمل أسماء قطع المحرّك: V660 Carb وV554 Piston وV770 Engine. غلافة من الإكوادور فوق حشوة نيكاراغوية وهندوراسية. قوية، بنكهات الجلد والقهوة السوداء والشوكولاتة — سيجارة الطريق وأمريكا العميقة.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"إكوادوري"},{"name":"Punch Upper Cut","color":"#722F37","force":"Full","story":"المجموعة الراقية لجنرال سيغار تحت اسم بانش. غلاف هندوراسي مادورو فوق تبغ نيكاراغوي-هندوراسي. شوكولاتة داكنة، خشب مدخَّن، فلفل. إنه الوجه الداكن لبانش — قويّ حيث تكون المجموعة الكلاسيكية سهلة.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Maduro من هندوراس"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"محفظة عائلة تورانيو، اشتُريت في أيلول/سبتمبر 2014 — العلامات فقط؛ توقّفت شركة Toraño Family Cigar، وبقي تشارلي تورانيو مستشارًا. وتوفّي كارلوس تورانيو في شباط/فبراير 2022. كان هذا الأطلس قد حذف «Carlos Toraño Panama» مختلَقًا (204)؛ أمّا علامة Toraño فحقيقية وتعيش هنا."}]' WHERE `name` = 'General Cigar';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; requalification : cigaraficionado.com « General Cigar Acquires All Toraño Brands » et halfwheel.com « General Cigar Co. Acquiring Toraño Brands » (septembre 2014 : General rachète tout le portefeuille de Toraño Family Cigar, pas la société, qui cesse ; Charlie Toraño consultant) ; cigar-coop.com « Carlos Toraño Passes Away » (février 2022)') WHERE `name` = 'General Cigar' AND COALESCE(`source`,'') NOT LIKE '%requalification :%';

-- ── Maya Selva Cigars ──
UPDATE `brands` SET `gamme` = '[{"name":"Villa Zamorano","color":"#6B4226","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"La ligne hondurienne de la maison, du nom de la vallée où poussent ses tabacs, produite à la Fábrica de Puros MSC de Danlí. Le recensement de cet atlas la prenait pour une fabrique à part."}]' WHERE `name` = 'Maya Selva Cigars';
UPDATE `brands` SET `gamme_en` = '[{"name":"Villa Zamorano","color":"#6B4226","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"The house''s Honduran line, named after the valley where its tobaccos grow, made at Fábrica de Puros MSC in Danlí. This atlas''s census took it for a separate factory."}]' WHERE `name` = 'Maya Selva Cigars';
UPDATE `brands` SET `gamme_es` = '[{"name":"Villa Zamorano","color":"#6B4226","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"La línea hondureña de la casa, con el nombre del valle donde crecen sus tabacos, producida en la Fábrica de Puros MSC de Danlí. El censo de este atlas la tomaba por una fábrica aparte."}]' WHERE `name` = 'Maya Selva Cigars';
UPDATE `brands` SET `gamme_de` = '[{"name":"Villa Zamorano","color":"#6B4226","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Die honduranische Linie des Hauses, benannt nach dem Tal, in dem ihre Tabake wachsen, hergestellt in der Fábrica de Puros MSC in Danlí. Die Zählung dieses Atlas hielt sie für eine eigene Fabrik."}]' WHERE `name` = 'Maya Selva Cigars';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Villa Zamorano","color":"#6B4226","force":"Medium","wrapper":"未公开","vitolas":[],"story":"公司的洪都拉斯系列，以其烟叶生长的山谷命名，在丹利的 Fábrica de Puros MSC 生产。本图集的普查曾把它当作另一家工厂。"}]' WHERE `name` = 'Maya Selva Cigars';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Villa Zamorano","color":"#6B4226","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"الخطّ الهندوراسي للدار، باسم الوادي الذي تنمو فيه أتبغته، يُنتج في Fábrica de Puros MSC في دانلي. وكان إحصاء هذا الأطلس يحسبه مصنعًا مستقلًّا."}]' WHERE `name` = 'Maya Selva Cigars';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; requalification : revuedestabacs.com « Maya Selva Cigares » et cigarpassion.ch (Villa Zamorano, la ligne hondurienne de Maya Selva, du nom de la vallée où poussent ses tabacs, produite à la Fábrica de Puros MSC de Danlí)') WHERE `name` = 'Maya Selva Cigars' AND COALESCE(`source`,'') NOT LIKE '%requalification :%';

-- ── Villiger ──
UPDATE `brands` SET `gamme` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"La gamme d''exception — hommage au Tessin, la Suisse italophone. Cape oscuro d''Équateur sur assemblage nicaraguayen et brésilien. Profil plus intense, chocolat noir et poivre long. La réponse suisse à la question de ce que l''Europe peut opposer aux grandes maisons du Nouveau Monde."},{"name":"Villiger Cuellar Nicaragua","color":"#5C3317","story":"Collaboration avec la famille Cuellar, à Estelí. Cape Colorado naturelle sur assemblage nicaraguayen pur. Le positionnement suisse dans le Nouveau Monde — précis, régulier, moins aventureux que Padrón mais très fiable."},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"Un nom de vieille marque cubaine, relancé par Villiger en 2007 comme cigare dominicain, roulé à l''ABAM — la fabrique de Villiger en République dominicaine, que cette fiche nomme ici. Le recensement de cet atlas le prenait pour une maison."}]' WHERE `name` = 'Villiger';
UPDATE `brands` SET `gamme_en` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"The exceptional range — tribute to the Italian-speaking Swiss region (Ticino). Ecuadorian Oscuro wrapper on Nicaragua/Brazil blend. More intense profile, dark chocolate and long pepper. Switzerland''s answer to what the continent can offer against the great New World cigars."},{"name":"Villiger Cuellar Nicaragua","color":"#5C3317","story":"Collaboration with the Cuellar family in Estelí. Natural Colorado wrapper on a pure Nicaraguan blend. The Swiss positioning in the New World — precise, consistent, less adventurous than Padrón but highly reliable."},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"An old Cuban brand name, relaunched by Villiger in 2007 as a Dominican cigar, rolled at ABAM — Villiger''s factory in the Dominican Republic, which this entry names here. This atlas''s census took it for a house."}]' WHERE `name` = 'Villiger';
UPDATE `brands` SET `gamme_es` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"La gama de excepción, homenaje a la región italófona de Suiza (el Tesino). Capa Oscuro ecuatoriana sobre ligada de Nicaragua y Brasil. Perfil más intenso, chocolate negro y pimienta larga. La respuesta suiza a la pregunta de qué puede ofrecer el continente frente a los grandes del New World."},{"name":"Villiger Cuellar Nicaragua","color":"#5C3317","story":"Colaboración con la familia Cuellar en Estelí. Capa Colorado natural sobre ligada nicaragüense pura. El posicionamiento suizo en el New World: preciso, regular, menos aventurero que Padrón pero muy fiable."},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"Un nombre de vieja marca cubana, relanzado por Villiger en 2007 como puro dominicano, liado en ABAM — la fábrica de Villiger en la República Dominicana, que esta ficha nombra aquí. El censo de este atlas lo tomaba por una casa."}]' WHERE `name` = 'Villiger';
UPDATE `brands` SET `gamme_de` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"Die Ausnahmelinie — eine Hommage an die italienischsprachige Schweiz (Tessin). Ecuadorianisches Oscuro-Deckblatt auf einer Mischung aus Nicaragua und Brasilien. Intensiveres Profil, Zartbitterschokolade und Langpfeffer. Die Schweizer Antwort auf die Frage, was der Kontinent den großen New-World-Zigarren entgegenzusetzen hat."},{"name":"Villiger Cuellar Nicaragua","color":"#5C3317","story":"Zusammenarbeit mit der Familie Cuellar in Estelí. Natürliches Colorado-Deckblatt auf reiner nicaraguanischer Mischung. Die schweizerische Position in der New World — genau, gleichmäßig, weniger wagemutig als Padrón, dafür sehr verlässlich."},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Ein alter kubanischer Markenname, 2007 von Villiger als dominikanische Zigarre neu lanciert, gerollt bei ABAM — der Fabrik von Villiger in der Dominikanischen Republik, die dieser Eintrag hier nennt. Die Zählung dieses Atlas hielt ihn für ein Haus."}]' WHERE `name` = 'Villiger';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"非凡系列——向瑞士的意大利语区（提契诺）致敬。厄瓜多尔 Oscuro 茄衣，配尼加拉瓜与巴西茄芯。风格更浓烈，带黑巧克力与荜拨。面对新世界的大牌，欧洲大陆能拿出什么？这是瑞士给出的答案。"},{"name":"Villiger Cuellar Nicaragua","color":"#5C3317","story":"与 Estelí 的 Cuellar 家族合作之作。天然 Colorado 茄衣，配纯尼加拉瓜茄芯。这是瑞士人在新世界的站位——精准、稳定，不如 Padrón 冒险，却非常可靠。"},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","wrapper":"未公开","vitolas":[],"story":"一个古巴老牌名，2007年由 Villiger 以多米尼加雪茄的身份重启，在 ABAM——Villiger 在多米尼加共和国的工厂——卷制，本词条在此点名。本图集的普查曾把它当作一家公司。"}]' WHERE `name` = 'Villiger';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"التشكيلة الاستثنائية — تحيّة إلى المنطقة الناطقة بالإيطالية في سويسرا (تيتشينو). غلاف Oscuro إكوادوري على خلطة من نيكاراغوا والبرازيل. طابع أشدّ كثافة، بشوكولاتة داكنة وفلفل طويل. وهو الجواب السويسري عن سؤال ما يمكن للقارة أن تقدّمه في مواجهة كبار العالم الجديد."},{"name":"Villiger Cuellar Nicaragua","color":"#5C3317","story":"تعاون مع عائلة Cuellar في Estelí. غلاف Colorado طبيعي على خلطة نيكاراغوية خالصة. إنه الموقع السويسري داخل العالم الجديد — دقيق ومنتظم، أقلّ مغامرة من Padrón لكنه موثوق جداً."},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"اسمُ علامة كوبية قديمة، أعادت Villiger إطلاقه سنة 2007 سيجارًا دومينيكيًّا، يُلفّ في ABAM — مصنع Villiger في جمهورية الدومينيكان الذي تسمّيه هذه البطاقة هنا. وكان إحصاء هذا الأطلس يحسبه دارًا."}]' WHERE `name` = 'Villiger';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; requalification : houseofgrauer.com « Villiger Cigars » et havanahouse.co.uk (Havana Club, ancienne marque cubaine relancée par Villiger en 2007 comme cigare dominicain, roulée à l''ABAM, la fabrique de Villiger en République dominicaine) — et les deux entrées de machine, Premium No. 6 et Export, retirées du gamme en application de la règle 187') WHERE `name` = 'Villiger' AND COALESCE(`source`,'') NOT LIKE '%requalification :%';

-- ── Rocky Patel ──
UPDATE `brands` SET `gamme` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"Le nom renvoie à l''origine des capes du premier assemblage, récoltées en 1992 — pas à l''âge du tabac vendu aujourd''hui. Cape Ecuador Connecticut sur tabacs honduriens et nicaraguayens. Notes de noisette grillée, caramel, bois clair. Mi-corsée à corsée, équilibrée ; la série Vintage reste l''une des propositions les plus narratives du marché : chaque millésime raconte une récolte.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"Lancée pour les 50 ans de Rocky Patel — l''homme, pas la marque. Assemblage hondurien-nicaraguayen complexe, cape d''Équateur cultivée en plein soleil. Notes de café, épices orientales, sous-bois. Format Toro, 50 x 152mm. Une gamme qui reste dans l''ombre des séries Vintage alors qu''elle en dit autant sur la maison.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Plein soleil d''Équateur"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"La gamme accessible de la maison. Formats Robusto et Toro, cape Connecticut, tabacs hondurien et nicaraguayen. Notes douces de crème et de noisette. Le premier Rocky Patel pour un néophyte — facile d''approche, régulier, gratifiant. Prix démocratique.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (Mexique)","vitolas":[],"story":"Les cigares d''Hamlet Paredes, ancien rouleur de Partagás et ambassadeur d''Habanos, engagé en 2015 — Tabaquero d''abord, puis Liberation et 25th Year. Paredes est parti en août 2022 ; la maison garde le nom et les lignes, et a arrêté Tabaquero."},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"La première marque de Rocky Patel, dans les années 1990, avant que la maison ne prenne son nom. Le recensement de cet atlas la prenait pour une maison hondurienne à part."}]' WHERE `name` = 'Rocky Patel';
UPDATE `brands` SET `gamme_en` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"The name refers to the origin of the wrappers used in the first blend, harvested in 1992 — not to the age of the tobacco sold today. Ecuador Connecticut wrapper over Honduran and Nicaraguan leaf. Toasted hazelnut, caramel, pale wood. A balanced medium-full, and the Vintage series remains one of the most narrative propositions on the market: each vintage tells of a harvest.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"Launched for Rocky Patel''s fiftieth birthday — the man, not the brand. A complex Honduran-Nicaraguan blend, Ecuadorian wrapper grown in full sun. Coffee, oriental spice, forest floor. Toro format, 50 x 152mm. A range that stays in the shadow of the Vintage series though it says just as much about the house.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Ecuadorian Sun-Grown"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"The house''s accessible range. Robusto and Toro formats, Connecticut wrapper, Honduran and Nicaraguan leaf. Gentle cream and hazelnut. The first Rocky Patel for a newcomer — easy to approach, consistent, rewarding. A democratic price.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (Mexico)","vitolas":[],"story":"The cigars of Hamlet Paredes, former Partagás roller and Habanos ambassador, hired in 2015 — Tabaquero first, then Liberation and 25th Year. Paredes left in August 2022; the house keeps the name and the lines, and discontinued Tabaquero."},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"Rocky Patel''s first brand, in the 1990s, before the house took his name. This atlas''s census took it for a separate Honduran house."}]' WHERE `name` = 'Rocky Patel';
UPDATE `brands` SET `gamme_es` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"El nombre remite al origen de las capas del primer ligado, cosechadas en 1992, no a la edad del tabaco que se vende hoy. Capa Ecuador Connecticut sobre tabacos hondureños y nicaragüenses. Avellana tostada, caramelo, madera clara. Un medio-fuerte equilibrado, y la serie Vintage sigue siendo una de las propuestas más narrativas del mercado: cada añada cuenta una cosecha.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"Lanzada por los 50 años de Rocky Patel, el hombre, no la marca. Ligado hondureño-nicaragüense complejo, capa ecuatoriana cultivada a pleno sol. Café, especias orientales, sotobosque. Formato Toro, 50 x 152mm. Una gama que permanece a la sombra de las series Vintage aunque diga otro tanto sobre la casa.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"De sol de Ecuador"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"La gama accesible de la casa. Formatos Robusto y Toro, capa Connecticut, tabacos hondureño y nicaragüense. Notas suaves de crema y avellana. El primer Rocky Patel para un neófito: fácil de abordar, regular, gratificante. Precio democrático.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (México)","vitolas":[],"story":"Los puros de Hamlet Paredes, antiguo torcedor de Partagás y embajador de Habanos, contratado en 2015 — Tabaquero primero, luego Liberation y 25th Year. Paredes se fue en agosto de 2022; la casa conserva el nombre y las líneas, y retiró Tabaquero."},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"La primera marca de Rocky Patel, en los años 1990, antes de que la casa tomara su nombre. El censo de este atlas la tomaba por una casa hondureña aparte."}]' WHERE `name` = 'Rocky Patel';
UPDATE `brands` SET `gamme_de` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"Der Name verweist auf die Herkunft der Deckblätter der ersten Mischung, geerntet 1992 — nicht auf das Alter des heute verkauften Tabaks. Deckblatt Ecuador Connecticut über honduranischem und nicaraguanischem Tabak. Geröstete Haselnuss, Karamell, helles Holz. Ein ausgewogenes Medium-Full, und die Vintage-Serie bleibt eines der erzählerischsten Angebote des Marktes: Jeder Jahrgang erzählt von einer Ernte.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"Zum 50. Geburtstag von Rocky Patel lanciert — dem Mann, nicht der Marke. Komplexe honduranisch-nicaraguanische Mischung, ecuadorianisches Deckblatt aus vollem Sonnenanbau. Kaffee, orientalische Gewürze, Waldboden. Format Toro, 50 x 152 mm. Eine Serie, die im Schatten der Vintage-Reihen bleibt, obwohl sie ebenso viel über das Haus erzählt.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Sonnenanbau aus Ecuador"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"Die zugängliche Serie des Hauses. Formate Robusto und Toro, Deckblatt Connecticut, honduranischer und nicaraguanischer Tabak. Milde Noten von Sahne und Haselnuss. Der erste Rocky Patel für Einsteiger — leicht zugänglich, gleichmäßig, dankbar. Ein demokratischer Preis.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"Die Zigarren von Hamlet Paredes, ehemaligem Partagás-Roller und Habanos-Botschafter, 2015 engagiert — zuerst Tabaquero, dann Liberation und 25th Year. Paredes ging im August 2022; das Haus behält Namen und Linien und stellte Tabaquero ein."},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Rocky Patels erste Marke, in den 1990ern, bevor das Haus seinen Namen annahm. Die Zählung dieses Atlas hielt sie für ein eigenes honduranisches Haus."}]' WHERE `name` = 'Rocky Patel';
UPDATE `brands` SET `gamme_zh` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"名字指的是首款配方所用茄衣的来历——那批茄衣收于 1992 年，而不是今天所售烟叶的年份。厄瓜多尔康涅狄格茄衣，包裹洪都拉斯与尼加拉瓜烟叶。烤榛子、焦糖、浅色木。中偏浓而均衡；Vintage 系列至今仍是市场上最有叙事性的构想之一：每一个年份都在讲一次收成。","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"为洛基·帕特尔五十岁而推出——是这个人，不是这个牌子。复杂的洪都拉斯－尼加拉瓜配方，茄衣来自厄瓜多尔的全日照种植。咖啡、东方香料、林下腐叶。Toro 规格，50 x 152 毫米。这个系列一直被 Vintage 各系列的光芒盖住，可它讲出的老号故事并不更少。","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"厄瓜多尔日光种植"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"这家老号的入门系列。Robusto 与 Toro 两种规格，康涅狄格茄衣，洪都拉斯与尼加拉瓜烟叶。奶油与榛子的柔和气息。给新手的第一支洛基·帕特尔——好上手、稳定、有回报。价格亲民。","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","wrapper":"圣安德烈斯（墨西哥）","vitolas":[],"story":"哈姆雷特·帕雷德斯的雪茄——他曾是 Partagás 的卷工与 Habanos 的大使，2015年受聘——先是 Tabaquero，再是 Liberation 与 25th Year。帕雷德斯2022年8月离开；公司保留名字与各线，停掉了 Tabaquero。"},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","wrapper":"未公开","vitolas":[],"story":"洛基·帕特尔的第一个品牌，1990年代，早于公司改用他的名字。本图集的普查曾把它当作另一家洪都拉斯公司。"}]' WHERE `name` = 'Rocky Patel';
UPDATE `brands` SET `gamme_ar` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"يشير الاسم إلى أصل أغلفة الخلطة الأولى، وقد جُنيت عام 1992 — لا إلى عمر التبغ المُباع اليوم. غلاف إكوادور كونيتيكت فوق تبغ هندوراسي ونيكاراغوي. بندق محمّص، كراميل، خشب فاتح. قوّة متوسطة-عالية متوازنة، وتبقى سلسلة Vintage من أكثر الطروحات سرديّة في السوق: كل سنة تروي حصادًا.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"أُطلقت في عيد ميلاد روكي باتيل الخمسين — الرجل لا العلامة. خلطة هندوراسية-نيكاراغوية معقّدة، وغلاف إكوادوري مزروع في الشمس الكاملة. قهوة، توابل شرقية، أرض غابة. قياس تورو، 50 × 152 مم. مجموعة تبقى في ظلّ سلاسل Vintage، مع أنها تقول عن الدار قدر ما تقوله تلك.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"مزروع في الشمس من الإكوادور"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"المجموعة السهلة لدى الدار. قياسا روبوستو وتورو، غلاف كونيتيكت، وتبغ هندوراسي ونيكاراغوي. نفحات ناعمة من القشدة والبندق. أول روكي باتيل للمبتدئ — سهل التناول، ثابت، مُجزٍ. وسعره في متناول الجميع.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","wrapper":"سان أندريس (المكسيك)","vitolas":[],"story":"سيجارات هاملت باريديس، لفّاف Partagás السابق وسفير Habanos، الذي استُقدم سنة 2015 — Tabaquero أوّلًا، ثم Liberation و25th Year. غادر باريديس في آب/أغسطس 2022؛ وتحتفظ الدار بالاسم والخطوط، وأوقفت Tabaquero."},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"أوّل علامة لروكي باتيل، في التسعينيات، قبل أن تتّخذ الدار اسمه. وكان إحصاء هذا الأطلس يحسبها دارًا هندوراسية مستقلّة."}]' WHERE `name` = 'Rocky Patel';
UPDATE `brands` SET `source` = CONCAT(COALESCE(`source`,''), ' ; requalification : rockypatel.com (Indian Tabac Cigar Company, la première marque de Rocky Patel, années 1990, avant que la maison ne prenne son nom)') WHERE `name` = 'Rocky Patel' AND COALESCE(`source`,'') NOT LIKE '%requalification :%';


INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` ELSE b.`gamme` END), 'machine', NOW()
  FROM `brands` b
  JOIN (SELECT 'history' champ UNION ALL SELECT 'gamme') c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE b.`name` IN ('Balmoral','Don Lucas','A.J. Fernandez','General Cigar','Maya Selva Cigars','Villiger','Rocky Patel')
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `maj` = NOW();

DELETE FROM `moderation_log` WHERE `acteur_nom` = 'migration 217';
INSERT INTO `moderation_log`
  (`acteur_id`, `acteur_nom`, `portee`, `action`, `cible_type`, `cible_id`, `detail`)
VALUES
  (NULL,'migration 217','systeme','lot_8_deux_dominicaines','marque',0,
   'Balmoral : la marque premium de Royal Agio, STG depuis 2020, retiree des Etats-Unis, roulee a General Cigar Dominicana pour l Europe. Don Lucas : fabrique-boutique de Punta Cana, 1992 selon la maison, 20th Anniversary vers 2017 — les deux dates ecrites'),
  (NULL,'migration 217','systeme','trois_non_ecrites','marque',0,
   'Hammer + Sickle : fermee par Klin Groupe en mai 2022. Las Cumbres : Jose Blanco chez E.P. Carrillo, aucune presse depuis 2017. Cabal : aucune presse du metier depuis 2015. La regle Ortega'),
  (NULL,'migration 217','systeme','cinq_requalifications','marque',0,
   'Sosa -> A.J. Fernandez (dec. 2016), Torano -> General Cigar (sept. 2014), Villa Zamorano -> Maya Selva, Havana Club -> Villiger (2007, ABAM), Indian Tabac -> Rocky Patel. Chacune dans le gamme de sa maison, six langues'),
  (NULL,'migration 217','systeme','villiger_machine_retiree','marque',0,
   'Le gamme de Villiger portait deux cigares de machine, Premium No. 6 et Export. La regle 187 les interdit : retires en six langues');

SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('Balmoral','Don Lucas')) = 2 AS deux_fiches,
  (SELECT `brands` LIKE '%Balmoral%' AND `brands` LIKE '%Don Lucas%' FROM `producer_countries` WHERE `id` = 'dominican') AS dominicaine_annonce,
  (SELECT `gamme` LIKE '%Sosa%' AND `gamme_ar` LIKE '%Sosa%' FROM `brands` WHERE `name` = 'A.J. Fernandez') AS sosa,
  (SELECT `gamme` NOT LIKE '%Premium No. 6%' AND `gamme_zh` NOT LIKE '%Export%' AND `gamme` LIKE '%Havana Club%' FROM `brands` WHERE `name` = 'Villiger') AS villiger_propre,
  (SELECT `gamme` LIKE '%Villa Zamorano%' FROM `brands` WHERE `name` = 'Maya Selva Cigars') AS zamorano,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 217') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
